#include <Servo.h>

// Создаем объекты сервоприводов
Servo servo1;
Servo servo2;

// Настройки
const int servo1Pin = 9;      // Пин для первого сервопривода
const int servo2Pin = 10;     // Пин для второго сервопривода
const int startAngle = 45;    // Начальный угол (в градусах)
const int endAngle = 135;     // Конечный угол (в градусах)
const int stepDelay = 20;     // Задержка между шагами (мс), влияет на скорость
const int pauseAtEnd = 500;   // Пауза в крайних точках (мс)

void setup() {
  // Присоединяем сервоприводы к пинам
  servo1.attach(servo1Pin);
  servo2.attach(servo2Pin);
  
  // Устанавливаем начальное положение
  servo1.write(startAngle);
  servo2.write(startAngle);
  
  // Даем сервам время занять позицию при включении
  delay(1000);
}

void loop() {
  // Сканируем первым сервоприводом
  scanServo(servo1);
  delay(200); // Небольшая пауза перед передачей эстафеты
  
  // Сканируем вторым сервоприводом
  scanServo(servo2);
  delay(200); // Пауза перед началом нового цикла
}

// Функция для сканирования одним сервоприводом
void scanServo(Servo servo) {
  // Движение от начального угла к конечному
  for (int pos = startAngle; pos <= endAngle; pos++) {
    servo.write(pos);
    delay(stepDelay);
  }
  delay(pauseAtEnd);

  // Возврат в исходное положение
  for (int pos = endAngle; pos >= startAngle; pos--) {
    servo.write(pos);
    delay(stepDelay);
  }
  delay(pauseAtEnd);
}
